ROOT=pathlib.Path(__file__).resolve().parents[1]
registry={}
for p in sorted((ROOT/'batches').glob('*.json')):
    if p.stem=='c-new-06': continue
    for s in json.loads(p.read_text(encoding='utf-8')).get('sources',[]): registry[s['id']]=s
for s in json.loads((ROOT.parent/'encyclopedia-revision/bibliography.json').read_text(encoding='utf-8')): registry[s['id']]=s
