def S(key,title,url,org,author,published,locator,kind='Manuel universitaire ouvert',limitation='Connaissance générale : ne constitue pas un caractère propre au cannabis.',access='full-text'):
    same=[s for s in registry.values() if s.get('url','').rstrip('/')==url.rstrip('/')]
    if same: return same[0]['id']
    sid='q2-cn06-'+key
    s=dict(id=sid,title=title,organization=org,url=url,verifiedAt='2026-11-16',author=author,published=published,passage=locator,access=access,documentKind=kind,limitation=limitation,consultation=dict(reader='c_science_pilot',date='2026-11-16',locator=locator,result='Passage indiqué effectivement ouvert et lu ; soutien précis paraphrasé dans les questions.'))
    sources.append(s); registry[sid]=s; return sid
def OS(key,section,slug,locator):
    return S(key,'Biology 2e — '+section,'https://openstax.org/books/biology-2e/pages/'+slug,'OpenStax, Rice University','Mary Ann Clark, Matthew Douglas et Jung Choi','2018-03-28',locator)
def Q(key,level,prompt,opts,explanation,subject,subjectkey,prop,objective,src,loc,support,form='identification',topic='genetics',category='genetics',rationale=None):
    shift=len(questions)%4; opts=opts[shift:]+opts[:shift]; answer=(-shift)%4
    q=dict(id='hemp-q2-cn06-'+key,topicId=topic,level=level,prompt=prompt,options=opts,answer=answer,explanation=explanation,articleId='ref-genetique-heredite',sourceIds=[src],editorial=dict(category=category,subject=subject,subjectKey=subjectkey,property=prop,expectedAnswer=opts[answer],learningObjective=objective,factKey=key,form=form,difficultyRationale=rationale or {1:'Repère de culture scientifique générale, sans prérequis technique.',2:'Notion de biologie intermédiaire demandant de distinguer des mécanismes voisins.',3:'Mécanisme moléculaire ou cellulaire spécialisé, rappelé sans prémisses.',4:'Connaissance experte portant sur un système précisément défini.'}[level],sourceEvidence=[dict(sourceId=src,locator=loc,support=support)]))
    questions.append(q)
